-- ADR-0502: vínculo privado temporário, sem publicação nem acesso no destino.
create table pcm.sso_anexo_localizacao_atualizada_gate(id boolean primary key default true check(id),habilitado boolean not null default false);
insert into pcm.sso_anexo_localizacao_atualizada_gate(id,habilitado) values(true,false);
create table pcm.sso_anexos_localizacao_atualizada(id uuid primary key default gen_random_uuid(),tipo_anexo text not null check(tipo_anexo in ('foto','documento')),anexo_id uuid not null,lote_id uuid not null,linha_chave text not null,cliente_id uuid not null references pcm.clientes(id),tipo_localizacao text not null check(tipo_localizacao in ('area','local','sublocal')),entidade_id uuid not null,decisao_revision integer not null check(decisao_revision>0),ator_id uuid not null references auth.users(id),request_id uuid not null unique,criado_em timestamptz not null default now(),unique(tipo_anexo,anexo_id),foreign key(lote_id,linha_chave) references pcm.sso_atualizacoes_localizacao(lote_id,linha_chave));
alter table pcm.sso_anexo_localizacao_atualizada_gate enable row level security;alter table pcm.sso_anexo_localizacao_atualizada_gate force row level security;
alter table pcm.sso_anexos_localizacao_atualizada enable row level security;alter table pcm.sso_anexos_localizacao_atualizada force row level security;
revoke all on pcm.sso_anexo_localizacao_atualizada_gate,pcm.sso_anexos_localizacao_atualizada from public,anon,authenticated,service_role;
create trigger sso_anexos_localizacao_atualizada_imutaveis before update or delete on pcm.sso_anexos_localizacao_atualizada for each row execute function pcm.sso_proteger_incorporacao_levantamento();
create function pcm.sso_vincular_anexo_localizacao_atualizada(p_request_id uuid,p_tipo_anexo text,p_anexo_id uuid,p_decisao_revision integer) returns jsonb language plpgsql security definer set search_path='' as $$
declare v_cliente uuid;v_lote uuid;v_chave text;v_decisao text;v_revision integer;v_atual pcm.sso_atualizacoes_localizacao%rowtype;v_ant pcm.sso_anexos_localizacao_atualizada%rowtype;v_id uuid;
begin
 if not coalesce((select habilitado from pcm.sso_anexo_localizacao_atualizada_gate where id),false) then raise exception 'vinculo_desabilitado' using errcode='55000'; end if;
 if auth.uid() is null or p_request_id is null or p_tipo_anexo is null or p_tipo_anexo not in ('foto','documento') or p_anexo_id is null or p_decisao_revision is null or p_decisao_revision<1 then raise exception 'parametros_invalidos' using errcode='22023'; end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('anexo-localizacao:'||p_request_id::text,0));
 if p_tipo_anexo='foto' then select f.cliente_id,f.lote_id,f.linha_chave into v_cliente,v_lote,v_chave from pcm.sso_fotos_levantamento f join storage.objects o on o.id=f.objeto_id and o.bucket_id='sso-levantamento-fotos' and split_part(o.name,'/',1)=f.cliente_id::text and split_part(o.name,'/',2)=f.lote_id::text join storage.buckets b on b.id=o.bucket_id and b.public is false where f.id=p_anexo_id for update of f;
 else select d.cliente_id,d.lote_id,d.linha_chave into v_cliente,v_lote,v_chave from pcm.sso_documentos_levantamento d join storage.objects o on o.id=d.objeto_id and o.bucket_id='sso-levantamento-documentos' and split_part(o.name,'/',1)=d.cliente_id::text and split_part(o.name,'/',2)=d.lote_id::text join storage.buckets b on b.id=o.bucket_id and b.public is false where d.id=p_anexo_id for update of d; end if;
 if v_cliente is null or config.sso_autorizar_acao('cadastro.aprovar',v_cliente) is not true or config.sso_autorizar_acao('cadastro.gerir',v_cliente) is not true then raise exception 'sem_acesso' using errcode='42501'; end if;
 select * into v_ant from pcm.sso_anexos_localizacao_atualizada where request_id=p_request_id;
 if found then if v_ant.ator_id is distinct from auth.uid() or v_ant.tipo_anexo is distinct from p_tipo_anexo or v_ant.anexo_id is distinct from p_anexo_id or v_ant.decisao_revision<>p_decisao_revision then raise exception 'request_id_conflitante' using errcode='23505'; end if;return jsonb_build_object('vinculoId',v_ant.id,'tipo',p_tipo_anexo,'anexoId',p_anexo_id,'requestId',p_request_id,'publicado',false); end if;
 select a.* into v_atual from pcm.sso_atualizacoes_localizacao a join pcm.sso_levantamentos l on l.id=a.lote_id and l.cliente_id=v_cliente where a.lote_id=v_lote and a.linha_chave=v_chave;
 if not found then raise exception 'localizacao_atualizada_indisponivel' using errcode='23514'; end if;
 if v_atual.tipo='area' then perform 1 from pcm.areas a where a.id=v_atual.entidade_id and a.cliente_id=v_cliente and a.ativo and a.deleted_at is null for key share;
 else perform 1 from pcm.locais l join pcm.areas a on a.id=l.area_id where l.id=v_atual.entidade_id and a.cliente_id=v_cliente and a.ativo and a.deleted_at is null and l.ativo and l.deleted_at is null for key share of l,a; end if;
 if not found then raise exception 'localizacao_indisponivel' using errcode='23514'; end if;
 if p_tipo_anexo='foto' then select d.decisao,d.revisao into v_decisao,v_revision from pcm.sso_decisoes_foto_levantamento d where d.foto_id=p_anexo_id order by d.revisao desc limit 1; if pcm.sso_foto_inadequada(p_anexo_id) then raise exception 'anexo_inadequado' using errcode='23514'; end if;
 else select d.decisao,d.revisao into v_decisao,v_revision from pcm.sso_decisoes_documento_levantamento d where d.documento_id=p_anexo_id order by d.revisao desc limit 1; if pcm.sso_documento_inadequado(p_anexo_id) then raise exception 'anexo_inadequado' using errcode='23514'; end if; end if;
 if v_revision is distinct from p_decisao_revision or (p_tipo_anexo='foto' and v_decisao is distinct from 'aceita') or (p_tipo_anexo='documento' and v_decisao is distinct from 'aceito') then raise exception 'decisao_invalida_ou_obsoleta' using errcode='40001'; end if;
 if exists(select 1 from pcm.sso_retiradas_anexo where tipo=p_tipo_anexo and anexo_id=p_anexo_id) then raise exception 'anexo_retirado' using errcode='23514'; end if;
 insert into pcm.sso_anexos_localizacao_atualizada(tipo_anexo,anexo_id,lote_id,linha_chave,cliente_id,tipo_localizacao,entidade_id,decisao_revision,ator_id,request_id) values(p_tipo_anexo,p_anexo_id,v_lote,v_chave,v_cliente,v_atual.tipo,v_atual.entidade_id,p_decisao_revision,auth.uid(),p_request_id) returning id into v_id;
 insert into audit.events(actor_id,action,entity,entity_id,payload) values(auth.uid(),'levantamento.anexo_localizacao_atualizada','sso_levantamentos',v_lote,jsonb_build_object('clienteId',v_cliente,'linhaChave',v_chave,'anexoId',p_anexo_id,'tipo',p_tipo_anexo,'entidadeId',v_atual.entidade_id,'requestId',p_request_id));
 return jsonb_build_object('vinculoId',v_id,'tipo',p_tipo_anexo,'anexoId',p_anexo_id,'requestId',p_request_id,'publicado',false);
end; $$;
revoke all on function pcm.sso_vincular_anexo_localizacao_atualizada(uuid,text,uuid,integer) from public,anon,authenticated,service_role;
create function pcm.sso_impedir_retirada_anexo_localizacao_vinculada() returns trigger language plpgsql security definer set search_path='' as $$ begin if exists(select 1 from pcm.sso_anexos_localizacao_atualizada v where v.tipo_anexo=new.tipo and v.anexo_id=new.anexo_id) then raise exception 'anexo_vinculado' using errcode='23514'; end if;return new; end; $$;
revoke all on function pcm.sso_impedir_retirada_anexo_localizacao_vinculada() from public,anon,authenticated,service_role;
create trigger sso_impedir_retirada_anexo_localizacao_vinculada before insert on pcm.sso_retiradas_anexo for each row execute function pcm.sso_impedir_retirada_anexo_localizacao_vinculada();
